import { useState } from "react";
import { PrismTabs, PrismTabsList, PrismTabsTrigger, PrismClosableTabTrigger, PrismTabsContent } from "@pydemia/prism";

export function TabsExample() {
  const [open, setOpen] = useState([{ id: "candidate-1", label: "김가상 후보자" }]);
  const [active, setActive] = useState("candidate-1");
  const close = (id: string) => {
    setOpen(tabs => tabs.filter(tab => tab.id !== id));
    if (active === id) setActive("list");
  };
  return <section data-prism="light">
    <PrismTabs value={active} onValueChange={setActive}>
      <PrismTabsList variant="fill" aria-label="열린 후보자 탭">
        <PrismTabsTrigger value="list">목록</PrismTabsTrigger>
        {open.map(tab => <PrismClosableTabTrigger key={tab.id} value={tab.id} label={tab.label} onClose={close} />)}
      </PrismTabsList>
      <PrismTabsContent value="list">후보자 목록</PrismTabsContent>
      {open.map(tab => <PrismTabsContent key={tab.id} value={tab.id}>{tab.label}</PrismTabsContent>)}
    </PrismTabs>
  </section>;
}

