import { useState } from "react";
import { PrismChatInput, PrismMessage, PrismCriteria } from "@pydemia/prism";

export function ChatExample({ busy = false, onSubmit, onStop }: {
  busy?: boolean;
  onSubmit: (text: string) => Promise<void>;
  onStop?: () => void;
}) {
  const [text, setText] = useState("");
  const [error, setError] = useState(false);
  const send = async (message: string) => {
    setError(false);
    try { await onSubmit(message); setText(""); }
