    <PrismCriteria items={["# 기술 분야", "**전문분야**를 확인합니다."]} />
    <PrismChatInput value={text} onValueChange={setText} onSubmit={message => { void send(message); }} busy={busy} onStop={onStop} />
  </section>;
}

