import { useRef, useState } from "react";
import { PrismSwitch, PrismTooltip, PrismInfoTooltip, PrismProgress, PrismFileDropzone, PrismFileAttach,
  type PrismAttachment } from "@pydemia/prism";

export function UtilityExample() {
  const nextId = useRef(0);
  const [enabled, setEnabled] = useState(true);
  const [busy, setBusy] = useState(false);
  const [files, setFiles] = useState<PrismAttachment[]>([]);
  const [error, setError] = useState("");
  function select(selected: File[]) {
    // The host owns upload requests and changes each status after the result.
    setFiles(current => [...current, ...selected.map(file => ({
      id: `file-${nextId.current++}`, name: file.name, status: "uploading" as const,
      sizeLabel: `${Math.max(1, Math.round(file.size / 1024))}KB`,
    }))]);
  }
  const remove = (id: string) => setFiles(current => current.filter(file => file.id !== id));
  return <section data-prism="light" style={{ display: "grid", gap: 16, minWidth: 0 }}>
    <PrismSwitch label="알림 사용" checked={enabled} onCheckedChange={setEnabled} />
    <div style={{ display: "flex", alignItems: "center", flexWrap: "wrap", gap: 8 }}>
      <PrismTooltip content="가상 설정의 설명입니다." side="bottom">
        <button type="button">설정 도움말</button>
      </PrismTooltip>
      <PrismInfoTooltip label="진행률 설명" content="업로드 결과에 따라 호스트가 진행률을 갱신합니다." />
    </div>
    <PrismProgress value={busy ? null : 65} showPercent label="가상 진행률" />
    <button type="button" onClick={() => setBusy(value => !value)}>{busy ? "진행률 표시" : "로딩 표시"}</button>
    <PrismFileDropzone files={files} onFilesSelected={select} onRemove={remove}
      onInvalid={reason => setError(reason === "partial" ? "일부 파일만 첨부되었습니다." : "파일을 확인해 주세요.")} />
    <PrismFileAttach files={files} onFilesSelected={select} onRemove={remove} accept=".xlsx,.csv,.pdf,.png,.jpg" />
    {files.some(file => file.status === "uploading") && <button type="button" onClick={() =>
      setFiles(current => current.map(file => file.status === "uploading" ? { ...file, status: "ready" } : file))}>
      가상 업로드 완료
    </button>}
    {error && <p role="alert">{error} <button type="button" onClick={() => setError("")}>닫기</button></p>}
  </section>;
}

