        profile={showMemo => <div>가상 후보 <button type="button" onClick={showMemo}>메모 보기</button></div>} />}
      {kind === "memo" && <PrismMemoPanel {...shared} subjectId="synthetic-candidate" beforeLeave={beforeLeave}>{memo}</PrismMemoPanel>}
      {kind === "position" && <PrismPositionPanel {...shared}><PrismPositionDetail company="가상전자" role="기술전략담당"
        items={[{ label: "산업", value: "전자" }, { label: "직무", value: "연구개발" }]}
        definition="가상 조직의 기술전략을 수립합니다." businessContext="합성 데이터로 패널 구성을 보여 줍니다."
        groups={[{ id: "expertise", title: "전문성", items: [{ id: "one", content: "연구개발 경험" }] },
          { id: "experience", title: "성공경험", items: [] }]}/></PrismPositionPanel>}
      {kind === "chat" && <PrismChatPanel {...shared} contentRef={chatContent} atBottom={atBottom}
        onScrollToBottom={() => { chatContent.current?.scrollTo({ top: chatContent.current.scrollHeight, behavior: "smooth" }); setAtBottom(true); }}
        messages={<><PrismMessage role="user">기술전략 경험을 알려 주세요.</PrismMessage>
          <PrismMessage role="assistant">{"가상 후보의 경험을 검토합니다. ".repeat(24)}</PrismMessage>
          {sent.map((text, index) => <PrismMessage key={index} role="user">{text}</PrismMessage>)}</>}
        composer={<PrismChatInput value={question} onValueChange={setQuestion} onSubmit={text => {
          setSent(current => [...current, text]); setQuestion(""); setAtBottom(false);
        }}/>} />}
    </div>
